export const VIEW_COMPOSE_ESTIMATE_MS = 26000;

export function viewComposeProgress(startedAt, now = Date.now()) {
  const start = Number(startedAt) || now;
  const elapsed = Math.max(0, now - start);
  let progress;
  let stage;

  if (elapsed < 3500) {
    progress = 0.06 + (elapsed / 3500) * 0.18;
    stage = 'Finding the strongest material';
  } else if (elapsed < 18000) {
    progress = 0.24 + ((elapsed - 3500) / 14500) * 0.52;
    stage = 'Shaping the reading path';
  } else if (elapsed < VIEW_COMPOSE_ESTIMATE_MS) {
    progress = 0.76 + ((elapsed - 18000) / 8000) * 0.15;
    stage = 'Adding the finishing layer';
  } else {
    progress = 0.91 + (1 - Math.exp(-(elapsed - VIEW_COMPOSE_ESTIMATE_MS) / 18000)) * 0.055;
    stage = 'Finishing the page';
  }

  const remaining = VIEW_COMPOSE_ESTIMATE_MS - elapsed;
  const timeLabel = remaining > 2500
    ? `About ${Math.max(5, Math.ceil(remaining / 5000) * 5)} seconds left`
    : 'Almost ready';

  return {
    elapsed,
    progress: Math.min(0.965, progress),
    percent: Math.round(Math.min(0.965, progress) * 100),
    stage,
    timeLabel,
  };
}
